mapper.select:
SELECT
    COUNT(*)
FROM member_rel_trip
WHERE trip_id = #{tripId}
  AND member_id = #{memberId}
  AND status = 'JOINED'

SELECT t.trip_id, t.title, t.start_date, t.end_date, t.status, t.member_limit, ( SELECT COUNT(*) FROM member_rel_trip mrt2 WHERE mrt2.trip_id = t.trip_id AND mrt2.status = 'JOINED' ) AS joined_member_count, t.trip_region_id, tr.trip_region_name, t.created_at FROM trip t INNER JOIN member_rel_trip mrt ON mrt.trip_id = t.trip_id AND mrt.member_id = #{memberId} AND mrt.status = 'JOINED' LEFT JOIN trip_region tr ON tr.trip_region_id = t.trip_region_id
AND t.trip_id < #{cursor}
AND t.title LIKE CONCAT('%', #{title}, '%')
AND t.trip_region_id = #{tripRegionId}
AND t.status = #{status}
AND t.end_date >= #{dateFrom}
AND t.start_date <= #{dateTo}
ORDER BY t.trip_id DESC LIMIT #{size}

SELECT tr.trip_region_id, tr.trip_region_code, tr.trip_region_name, tr.image_url, tr.latitude, tr.longitude, tr.use_yn, tr.created_at FROM trip_region tr INNER JOIN trip t ON t.trip_id = #{tripId} AND t.trip_region_id IS NULL LEFT JOIN trip_candidate tc ON tc.trip_region_id = tr.trip_region_id AND tc.trip_id = #{tripId} AND tc.selected_yn = 'Y'
AND tr.use_yn = 'Y' AND tc.trip_candidate_id IS NULL
ORDER BY RAND() LIMIT #{cnt}
